content:
(() => {
    'use strict';

    const VERSION = '2.1.4';
    const APP_KEY = '__TT_ENHANCED_TOOLS_V1__';
    const STYLE_ID = 'tt-enhanced-tools-style';
    const ROOT_ID = 'tt-enhanced-tools-root';
    const QR_TOGGLE_ID = 'tt-qr-collapse-toggle';
    const REGEN_ID = 'tt-regenerate-button';
    const TOAST_MARK = '__tt_enhanced_toast_mute_v3__';
    const TOAST_ERROR_MARK = '__tt_enhanced_toast_error_v1__';

    const FLOAT_TITLES = {
        floatingPrompt: "Author's Note",
        cfgConfig: 'CFG Scale',
        logprobsViewer: 'Xác suất Token',
        'qr--popout': 'Cửa sổ Quick Reply nổi',
        'th-asr-widget-v3': 'Widget nổi TavernHelper',
        'wxhl-cygf-ball': 'Workshop',
    };

    function resolveHostWindow() {
        const candidates = [];
        try { candidates.push(window.parent); } catch { /* ignore */ }
        try { candidates.push(window.top); } catch { /* ignore */ }
        candidates.push(window);

        for (const candidate of candidates) {
            try {
                if (candidate && candidate.document?.body && (
                    candidate.document.querySelector('#send_form') ||
                    candidate.document.querySelector('#chat')
                )) {
                    return candidate;
                }
            } catch { /* ignore */ }
        }

        try {
            if (window.parent?.document?.body) return window.parent;
        } catch { /* ignore */ }
        return window;
    }

    const HOST = resolveHostWindow();
    const DOC = HOST.document;
    const IS_HOST_FRAME = HOST === window;

    try {
        HOST[APP_KEY]?.destroy?.();
    } catch { /* ignore */ }
    if (!IS_HOST_FRAME) {
        try { window[APP_KEY]?.destroy?.(); } catch { /* ignore */ }
    }

    const storage = {
        get(key, fallback) {
            for (const area of [HOST.localStorage, window.localStorage]) {
                try {
                    const value = area.getItem(key);
                    if (value !== null) return value;
                } catch { /* ignore */ }
            }
            return fallback;
        },
        set(key, value) {
            for (const area of [HOST.localStorage, window.localStorage]) {
                try {
                    area.setItem(key, String(value));
                    return;
                } catch { /* ignore */ }
            }
        },
    };

    function readBool(key, fallback) {
        const value = storage.get(key, null);
        if (value === null) return fallback;
        return value === 'true' || value === '1';
    }

    function readJson(key, fallback) {
        try {
            const value = storage.get(key, null);
            return value === null ? fallback : JSON.parse(value);
        } catch {
            return fallback;
        }
    }

    function readString(key, fallback) {
        const value = storage.get(key, null);
        return value === null ? fallback : String(value);
    }

    function readNumber(key, fallback, min = -Infinity, max = Infinity) {
        const value = Number(storage.get(key, fallback));
        if (!Number.isFinite(value)) return fallback;
        return Math.min(max, Math.max(min, value));
    }

    const state = {
        destroyed: false,
        muteReloadToast: readBool('tt-tools:mute-reload-toast', true),
        qrCollapsed: readBool('tt-tools:qr-collapsed', true),
        enableRegenerate: readBool('tt-tools:enable-regenerate', true),
        autoConfirmImports: readBool('tt-tools:auto-confirm-imports', true),
        scrollToLatestOnDone: readBool('tt-tools:scroll-latest-on-done', true),
        vibrateOnDone: readBool('tt-tools:vibrate-on-done', false),
        desktopNotifyOnDone: readBool('tt-tools:desktop-notify-on-done', false),
        autoRetryOnError: readBool('tt-tools:auto-retry-on-error', false),
        retryIntervalSeconds: readNumber('tt-tools:retry-interval-seconds', 1, 0.2, 60),
        retryMaxAttempts: readNumber('tt-tools:retry-max-attempts', 2, 1, 10),
        enableQrEnhance: readBool('tt-tools:enable-qr-enhance', true),
        qrToggleSide: readString('tt-tools:qr-toggle-side', 'right') === 'left' ? 'left' : 'right',
        collectShortcuts: readBool('tt-tools:collect-shortcuts', true),
        showLauncher: readBool('tt-tools:show-launcher', false),
        autoCollect: readBool('tt-tools:auto-collect', false),
        autoCollectBaseline: null,
        activeTab: 'quick',
        panelOpen: false,
        pickMode: false,
        pickCleanup: null,
        managed: new Map(),
        customFloatNames: readJson('tt-tools:custom-float-names', {}),
        customSelectors: readJson('tt-tools:custom-float-selectors', []),
        toastPatches: [],
        cleanups: [],
        timers: new Set(),
        observer: null,
        bodyObserver: null,
        observedNodes: new WeakSet(),
        lastFloatSignature: '',
        lastShortcutSignature: '',
        lastFloatingCount: 0,
        lastToggleTrace: null,
        hideObservers: new Map(),
        autoConfirmHandled: new WeakSet(),
        generationWatchers: [],
        generationSequence: 0,
        generationActive: false,
        activeGenerationType: '',
        postEffectGeneration: 0,
        retryState: { attempts: 0, scheduled: false, expected: false, timer: null },
        pendingGenerationResult: null,
        generationWaitTimer: null,
        lastGenerationStartedAt: 0,
        lastGenerationErrorAt: 0,
        chatLengthAtGenerationStart: 0,
        generationDebug: [],
        scrollCorrection: null,
        generationEndedForSequence: 0,
        generationEndedAt: 0,
        lastMessageRenderAt: 0,
        pendingRenderSignature: '',
        pendingRenderStableCount: 0,
        openingKeys: new Set(),
        openTimers: new Map(),
    };

    if (!Array.isArray(state.customSelectors)) state.customSelectors = [];
    if (!state.customFloatNames || typeof state.customFloatNames !== 'object' || Array.isArray(state.customFloatNames)) state.customFloatNames = {};

    function getContext() {
        const getters = [
            () => HOST.SillyTavern?.getContext?.(),
            () => window.SillyTavern?.getContext?.(),
            () => HOST.TavernHelper?.getContext?.(),
            () => window.TavernHelper?.getContext?.(),
        ];
        for (const getter of getters) {
            try {
                const context = getter();
                if (context) return context;
            } catch { /* ignore */ }
        }
        return null;
    }

    function qs(selector, root = DOC) {
        try { return root?.querySelector?.(selector) ?? null; } catch { return null; }
    }

    function qsa(selector, root = DOC) {
        try { return Array.from(root?.querySelectorAll?.(selector) ?? []); } catch { return []; }
    }

    function createElement(tag, className = '', text = '') {
        const element = DOC.createElement(tag);
        if (className) element.className = className;
        if (text) element.textContent = text;
        return element;
    }

    function escapeSelector(value) {
        try {
            if (HOST.CSS?.escape) return HOST.CSS.escape(value);
        } catch { /* ignore */ }
        return String(value).replace(/[^\w-]/g, (character) => `\\${character}`);
    }

    function getCssPath(element) {
        if (!element || element.nodeType !== 1) return '';
        if (element.id) return `#${escapeSelector(element.id)}`;

        const parts = [];
        let cursor = element;
        while (cursor && cursor.nodeType === 1 && cursor !== DOC.body && cursor !== DOC.documentElement) {
            if (cursor.id) {
                parts.unshift(`#${escapeSelector(cursor.id)}`);
                break;
            }
            let part = cursor.localName || cursor.tagName.toLowerCase();
            const parent = cursor.parentElement;
            if (parent) {
                const sameTag = Array.from(parent.children).filter(child => child.localName === cursor.localName);
                if (sameTag.length > 1) part += `:nth-of-type(${sameTag.indexOf(cursor) + 1})`;
            }
            parts.unshift(part);
            cursor = parent;
        }
        return parts.join(' > ');
    }

    function showToast(type, message) {
        const toastr = HOST.toastr || window.toastr;
        try {
            if (toastr && typeof toastr[type] === 'function') {
                toastr[type](message, 'Hộp công cụ nâng cao SillyTavern của Minh Thiên');
                return;
            }
        } catch { /* ignore */ }
        const logger = type === 'error' ? console.error : console.info;
        logger('[TT Enhanced Tools]', message);
    }

    function shouldMuteReloadToast(message, title) {
        const body = String(message ?? '');
        const head = String(title ?? '');
        const combined = `${head}\n${body}`;
        if (!/正则|regex|biểu thức chính quy/i.test(combined)) return false;
        return /(重新加载|刷新|重载|làm mới|tải lại)(?:了)?(?:当前)?(?:聊天|对话|đoạn chat|cuộc trò chuyện)|(?:Reload|Refresh)(?:ing|ed)?\s+(?:the\s+)?chat|(?:the\s+)?chat\s+(?:was\s+)?(?:reloaded|refreshed)/i.test(combined);
    }

    function installToastr(toastrObject) {
        if (!toastrObject) return false;
        let installed = false;

        if (typeof toastrObject.info === 'function' && !toastrObject.info[TOAST_MARK]) {
            const original = toastrObject.info;
            const wrapped = function (message, title, options) {
                if (state.muteReloadToast && shouldMuteReloadToast(message, title)) {
                    console.debug('[TT Enhanced Tools] blocked regex reload toast', { title, message });
                    return undefined;
                }
                return original.apply(this, arguments);
            };
            wrapped[TOAST_MARK] = true;
            toastrObject.info = wrapped;
            state.toastPatches.push({ target: toastrObject, property: 'info', original, wrapped });
            installed = true;
        }

        if (typeof toastrObject.error === 'function' && !toastrObject.error[TOAST_ERROR_MARK]) {
            const original = toastrObject.error;
            const wrapped = function (message, title, options) {
                if (isRetryableGenerationError(message, title)) scheduleGenerationRetry();
                return original.apply(this, arguments);
            };
            wrapped[TOAST_ERROR_MARK] = true;
            toastrObject.error = wrapped;
            state.toastPatches.push({ target: toastrObject, property: 'error', original, wrapped });
            installed = true;
        }

        return installed;
    }

    function installToastrEverywhere() {
        installToastr(window.toastr);
        try { installToastr(window.parent?.toastr); } catch { /* ignore */ }
        try { installToastr(window.top?.toastr); } catch { /* ignore */ }
        installToastr(HOST.toastr);
    }

    function restoreToastr() {
        for (const patch of state.toastPatches.splice(0)) {
            try {
                if (patch.target[patch.property] === patch.wrapped) patch.target[patch.property] = patch.original;
            } catch { /* ignore */ }
        }
    }

    function injectStyle() {
        if (qs(`#${STYLE_ID}`)) return;
        const style = createElement('style');
        style.id = STYLE_ID;
        style.textContent = `#${ROOT_ID} { position: fixed; inset: 0; z-index: 2147483000; pointer-events: none; color: var(--SmartThemeBodyColor, #e8e8e8); font-family: var(--mainFontFamily, inherit); font-size: 14px; line-height: 1.45; }
#${ROOT_ID}, #${ROOT_ID} * { box-sizing: border-box; }
#${ROOT_ID} button { font: inherit; }
#tt-toolbox-launcher { position: fixed; right: 14px; bottom: calc(var(--bottomFormBlockSize, 42px) + 22px); width: 42px; height: 42px; border-radius: 999px; border: 1px solid var(--SmartThemeBorderColor, #555); background: var(--SmartThemeBlurTintColor, rgba(36,36,37,.94)); color: var(--SmartThemeBodyColor, #eee); box-shadow: 0 8px 24px rgba(0,0,0,.38); display: flex; align-items: center; justify-content: center; cursor: pointer; pointer-events: auto; opacity: .88; transition: transform .15s ease, opacity .15s ease, box-shadow .15s ease; z-index: 3; }
#tt-toolbox-launcher:hover { opacity: 1; transform: translateY(-2px); box-shadow: 0 10px 28px rgba(0,0,0,.46); }
#tt-toolbox-launcher.tt-hidden { display: none !important; }
#tt-toolbox-launcher .fa-solid { font-size: 17px; }
#tt-toolbox-launcher-badge { position: absolute; top: -5px; right: -5px; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 999px; background: #d9534f; color: #fff; font-size: 11px; line-height: 18px; text-align: center; display: none; }
#tt-toolbox-overlay { position: fixed; inset: 0; z-index: 1; display: none; background: rgba(0,0,0,.42); backdrop-filter: blur(2px); pointer-events: auto; }
#tt-toolbox-overlay.tt-visible { display: block; }
#tt-toolbox-panel { position: fixed; left: 50%; top: 50%; transform: translate(-50%, -50%); z-index: 2; width: min(560px, calc(100vw - 16px)); max-width: calc(100vw - 16px); max-height: calc(100dvh - 16px); min-width: 0; min-height: 0; border: 1px solid var(--SmartThemeBorderColor, #555); border-radius: 14px; background: var(--SmartThemeBlurTintColor, rgba(30,30,32,.98)); box-shadow: 0 18px 52px rgba(0,0,0,.52); overflow: hidden; pointer-events: auto; display: flex; flex-direction: column; backdrop-filter: blur(12px); }
#tt-toolbox-panel.tt-hidden { display: none !important; }
#tt-toolbox-header { position: sticky; top: 0; z-index: 6; flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 9px 10px; border-bottom: 1px solid var(--SmartThemeBorderColor, #555); cursor: grab; touch-action: none; user-select: none; background: rgba(255,255,255,.035); }
#tt-toolbox-header:active { cursor: grabbing; }
#tt-toolbox-title { display: flex; align-items: center; gap: 7px; min-width: 0; font-weight: 600; }
#tt-toolbox-title small { opacity: .5; font-weight: 400; font-size: 10px; }
#tt-toolbox-header-actions { display: flex; flex: 0 0 auto; gap: 3px; }
.tt-toolbox-icon-btn { width: 27px; height: 27px; padding: 0; border: 0; border-radius: 7px; background: transparent; color: inherit; cursor: pointer; opacity: .72; }
.tt-toolbox-icon-btn:hover { opacity: 1; background: rgba(255,255,255,.09); }
#tt-toolbox-tabs { flex: 0 0 auto; display: flex; gap: 4px; padding: 7px 9px 0; }
.tt-toolbox-tab { flex: 1; border: 1px solid transparent; border-radius: 8px 8px 0 0; padding: 7px 6px; background: transparent; color: inherit; cursor: pointer; opacity: .62; }
.tt-toolbox-tab:hover { opacity: .9; background: rgba(255,255,255,.05); }
.tt-toolbox-tab.tt-active { opacity: 1; background: rgba(255,255,255,.09); border-color: var(--SmartThemeBorderColor, #555); border-bottom-color: transparent; }
#tt-toolbox-body { padding: 9px; overflow-y: auto; min-height: 0; }
.tt-toolbox-pane[hidden] { display: none !important; }
.tt-toolbox-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 9px; border: 1px solid var(--SmartThemeBorderColor, #555); border-radius: 9px; margin-bottom: 7px; background: rgba(255,255,255,.025); }
.tt-toolbox-row-copy { min-width: 0; }
.tt-toolbox-row-copy strong { display: block; font-weight: 600; }
.tt-toolbox-row-copy small { display: block; opacity: .62; margin-top: 2px; line-height: 1.35; }
.tt-toolbox-action { flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center; gap: 5px; min-height: 30px; padding: 5px 9px; border: 1px solid var(--SmartThemeBorderColor, #666); border-radius: 8px; background: rgba(255,255,255,.065); color: inherit; cursor: pointer; white-space: nowrap; }
.tt-toolbox-action:hover { background: rgba(255,255,255,.12); }
.tt-toolbox-action:disabled { opacity: .42; cursor: not-allowed; }
.tt-toolbox-action.tt-danger { border-color: rgba(217,83,79,.65); color: #ffb3b0; }
.tt-toolbox-action.tt-primary { border-color: rgba(76,175,80,.65); color: #b7efb9; }
.tt-toolbox-switch { flex: 0 0 auto; position: relative; width: 38px; height: 22px; border-radius: 999px; border: 1px solid var(--SmartThemeBorderColor, #666); background: rgba(255,255,255,.12); cursor: pointer; padding: 0; transition: background .15s ease; }
.tt-toolbox-switch::after { content: ''; position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: 50%; background: rgba(255,255,255,.88); transition: transform .15s ease; }
.tt-toolbox-switch.tt-on { background: rgba(76,175,80,.72); }
.tt-toolbox-switch.tt-on::after { transform: translateX(16px); }
.tt-segmented { display: inline-flex; padding: 2px; border: 1px solid var(--SmartThemeBorderColor, #555); border-radius: 8px; background: rgba(255,255,255,.04); flex: 0 0 auto; }
.tt-segmented button { border: 0; border-radius: 6px; padding: 4px 11px; background: transparent; color: inherit; cursor: pointer; opacity: .6; }
.tt-segmented button.tt-active { opacity: 1; background: rgba(255,255,255,.13); }
.tt-retry-inputs { display: inline-flex; align-items: center; gap: 4px; flex: 0 0 auto; font-size: 12px; }
.tt-number-input { width: 52px; min-height: 28px; padding: 2px 4px; border: 1px solid var(--SmartThemeBorderColor, #666); border-radius: 7px; background: rgba(255,255,255,.06); color: inherit; text-align: center; }
.tt-number-input:disabled { opacity: .45; }
.tt-toolbox-section-title { margin: 11px 1px 6px; font-size: 12px; font-weight: 600; opacity: .76; }
#tt-toolbox-floating-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; margin-bottom: 7px; }
#tt-toolbox-floating-actions .tt-toolbox-action { width: 100%; }
#tt-toolbox-auto-row { display: flex; align-items: center; gap: 7px; margin: 5px 1px 9px; opacity: .85; cursor: pointer; }
#tt-toolbox-auto-row input { accent-color: #4caf50; }
#tt-floating-list { display: flex; flex-direction: column; gap: 5px; max-height: 34vh; overflow-y: auto; }
.tt-float-item { display: flex; align-items: center; gap: 7px; padding: 7px 8px; border: 1px solid var(--SmartThemeBorderColor, #555); border-radius: 8px; background: rgba(255,255,255,.025); }
.tt-float-status { width: 8px; height: 8px; flex: 0 0 auto; border-radius: 50%; background: #777; box-shadow: 0 0 0 2px rgba(255,255,255,.06); }
.tt-float-status.tt-visible { background: #4caf50; }
.tt-float-name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tt-float-name small { opacity: .5; font-size: 10px; margin-left: 4px; }
.tt-float-actions { display: flex; gap: 3px; flex: 0 0 auto; }
.tt-float-actions .tt-toolbox-icon-btn { width: 25px; height: 25px; }
.tt-float-empty { padding: 14px 8px; text-align: center; opacity: .55; font-size: 12px; }
#tt-toolbox-footer { padding: 5px 10px 7px; font-size: 10px; opacity: .42; text-align: right; border-top: 1px solid rgba(255,255,255,.055); }
#tt-pick-hint { position: fixed; top: 14px; left: 50%; transform: translateX(-50%); z-index: 2147483647; display: flex; align-items: center; gap: 10px; padding: 9px 12px; border: 1px solid rgba(255,255,255,.32); border-radius: 10px; background: rgba(20,20,22,.95); color: #fff; box-shadow: 0 10px 35px rgba(0,0,0,.5); pointer-events: auto; font-size: 13px; }
#tt-pick-hint button { border: 1px solid rgba(255,255,255,.3); border-radius: 6px; background: rgba(255,255,255,.1); color: #fff; padding: 3px 8px; cursor: pointer; }
body.tt-fw-pick-mode, body.tt-fw-pick-mode * { cursor: crosshair !important; }
.tt-force-hidden { display: none !important; }
.tt-fw-flash { outline: 3px solid #ffd45c !important; outline-offset: 2px !important; animation: tt-fw-pulse .7s ease 2; }
@keyframes tt-fw-pulse { 50% { outline-color: transparent; } }

#${REGEN_ID} { order: 2; display: flex; align-items: center; justify-content: center; cursor: pointer; opacity: .72; }
#${REGEN_ID}:hover { opacity: 1; filter: brightness(1.15); }
#${REGEN_ID}.tt-busy { pointer-events: none; opacity: .38; }
#${REGEN_ID}.tt-busy .fa-solid { animation: tt-spin .8s linear infinite; }
@keyframes tt-spin { to { transform: rotate(360deg); } }

#qr--bar.tt-qr-enhanced { display: flex !important; align-items: center !important; justify-content: flex-start !important; flex-wrap: nowrap !important; gap: 3px !important; width: 100% !important; max-width: 100% !important; padding: 1px 2px !important; overflow: hidden !important; }
#qr--bar.tt-qr-enhanced.tt-qr-expanded { flex-wrap: wrap !important; overflow-x: hidden !important; overflow-y: auto !important; max-height: 34vh !important; }
#qr--bar.tt-qr-enhanced.tt-qr-collapsed { max-height: calc(var(--bottomFormBlockSize, 2.2rem) + 10px) !important; }
#qr--bar.tt-qr-enhanced > .qr--buttons { display: contents !important; width: auto !important; margin: 0 !important; padding: 0 !important; gap: 0 !important; }
#qr--bar.tt-qr-enhanced > .qr--buttons > .qr--buttons { display: contents !important; }
#qr--bar.tt-qr-enhanced .qr--button { flex: 0 0 auto !important; margin: 0 !important; max-width: none !important; white-space: nowrap !important; }
#qr--bar.tt-qr-enhanced.tt-qr-toggle-at-right { padding-right: 3.4em !important; }
#qr--bar.tt-qr-enhanced.tt-qr-toggle-at-left { padding-left: 3.4em !important; }
#${QR_TOGGLE_ID} { position: absolute !important; top: 50% !important; transform: translateY(-50%) !important; z-index: 8 !important; min-width: 24px; height: 24px; padding: 0 6px; border: 1px solid var(--SmartThemeBorderColor, #666); border-radius: 8px; background: var(--SmartThemeBlurTintColor, rgba(35,35,36,.98)); color: var(--SmartThemeBodyColor, #eee); cursor: pointer; display: inline-flex; align-items: center; justify-content: center; gap: 4px; font-size: 11px; opacity: .9; }
#${QR_TOGGLE_ID}:hover { opacity: 1; }
#${QR_TOGGLE_ID}.tt-qr-toggle-right { right: 3px !important; left: auto !important; }
#${QR_TOGGLE_ID}.tt-qr-toggle-left { left: 3px !important; right: auto !important; }
#${QR_TOGGLE_ID} .tt-qr-count { font-size: 9px; opacity: .7; }
#tt-shortcut-bar { display: contents !important; }
.tt-shortcut-button { flex: 0 0 auto !important; margin: 0 !important; max-width: 12em !important; overflow: hidden !important; text-overflow: ellipsis !important; white-space: nowrap !important; color: var(--SmartThemeBodyColor, #eee) !important; border: 1px solid var(--SmartThemeBorderColor, #666) !important; border-radius: 10px !important; padding: 3px 6px !important; background: transparent !important; cursor: pointer !important; display: inline-flex !important; align-items: center !important; justify-content: center !important; font-size: inherit !important; }
.tt-shortcut-button:hover { background: #4d4d4d !important; }
.tt-shortcut-button.tt-shortcut-hidden { opacity: .52 !important; border-style: dashed !important; }
.tt-shortcut-button .tt-shortcut-icon { margin-right: 4px; opacity: .72; }
.tt-shortcut-preview { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 5px; }
.tt-shortcut-chip { display: inline-flex; align-items: center; gap: 4px; max-width: 100%; padding: 3px 7px; border: 1px solid var(--SmartThemeBorderColor, #555); border-radius: 999px; background: rgba(255,255,255,.04); font-size: 11px; }
.tt-shortcut-chip small { opacity: .48; }
`;
        (DOC.head || DOC.documentElement).appendChild(style);
    }
    function ensureRegenerateButton() {
        if (!state.enableRegenerate) {
            qs(`#${REGEN_ID}`)?.remove();
            return;
        }
        const rightSendForm = qs('#rightSendForm');
        if (!rightSendForm) return;

        let button = qs(`#${REGEN_ID}`);
        if (!button) {
            button = createElement('div', 'fa-solid fa-rotate-right interactable');
            button.id = REGEN_ID;
            button.setAttribute('role', 'button');
            button.setAttribute('tabindex', '0');
            button.setAttribute('aria-label', 'Tạo lại phản hồi trước');
            button.title = 'Tạo lại phản hồi trước';
            button.addEventListener('click', (event) => {
                event.preventDefault();
                event.stopPropagation();
                void doRegenerate();
            });
            button.addEventListener('keydown', (event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                    event.preventDefault();
                    void doRegenerate();
                }
            });
        }
        const sendButton = qs('#send_but');
        if (button.parentElement !== rightSendForm || (sendButton && button.nextElementSibling !== sendButton)) {
            if (sendButton?.parentElement === rightSendForm) sendButton.insertAdjacentElement('beforebegin', button);
            else rightSendForm.appendChild(button);
        }
        syncRegenerateState();
    }

    function isGenerating() {
        if (DOC.body?.dataset?.generating === 'true') return true;
        const stopButton = qs('#mes_stop');
        if (stopButton) {
            const style = HOST.getComputedStyle?.(stopButton);
            if (style && style.display !== 'none' && style.visibility !== 'hidden') {
                const rect = stopButton.getBoundingClientRect();
                if (rect.width > 0 && rect.height > 0) return true;
            }
        }
        return false;
    }

    function syncRegenerateState() {
        const button = qs(`#${REGEN_ID}`);
        if (!button) return;
        const busy = isGenerating();
        button.classList.toggle('tt-busy', busy);
        button.setAttribute('aria-disabled', String(busy));
        button.title = busy ? 'Đang tạo phản hồi...' : 'Tạo lại phản hồi trước';
    }

    async function doRegenerate() {
        if (state.destroyed) return;
        if (isGenerating()) {
            showToast('info', 'Đang trong quá trình tạo, vui lòng đợi.');
            return;
        }

        const button = qs(`#${REGEN_ID}`);
        button?.classList.add('tt-busy');
        try {
            const option = qs('#option_regenerate');
            const jq = HOST.jQuery;
            if (option && jq?._data?.(option, 'events')?.click) {
                jq(option).trigger('click');
                return;
            }

            const context = getContext();
            if (context?.executeSlashCommandsWithOptions) {
                await context.executeSlashCommandsWithOptions('/regenerate', { showOutput: false });
                return;
            }

            if (option) {
                option.dispatchEvent(new HOST.MouseEvent('click', { bubbles: true, cancelable: true }));
                return;
            }

            if (context?.generate) {
                await context.generate('regenerate');
                return;
            }

            throw new Error('Không tìm thấy lối vào tạo lại khả dụng.');
        } catch (error) {
            console.error('[TT Enhanced Tools] regenerate failed', error);
            showToast('error', 'Tạo lại thất bại, vui lòng kiểm tra console.');
        } finally {
            setTimeout(() => button?.classList.remove('tt-busy'), 1200);
        }
    }

    function updateQrToggle(bar, toggle) {
        if (!bar || !toggle) return;
        const count = bar.querySelectorAll('.qr--button').length;
        const icon = toggle.querySelector('i');
        const counter = toggle.querySelector('.tt-qr-count');
        toggle.setAttribute('aria-expanded', String(!state.qrCollapsed));
        toggle.title = state.qrCollapsed ? `Mở rộng tất cả nút tắt (${count} nút)` : `Thu gọn nút tắt thành một dòng (${count} nút)`;
        if (icon) icon.className = `fa-solid ${state.qrCollapsed ? 'fa-chevron-down' : 'fa-chevron-up'}`;
        if (counter) counter.textContent = count > 0 ? String(count) : '';
    }

    function applyQrState() {
        for (const bar of qsa('#qr--bar')) {
            if (!state.enableQrEnhance) {
                bar.classList.remove('tt-qr-enhanced', 'tt-qr-collapsed', 'tt-qr-expanded', 'tt-qr-toggle-at-left', 'tt-qr-toggle-at-right');
                qs(`#${QR_TOGGLE_ID}`, bar)?.remove();
                continue;
            }

            bar.classList.add('tt-qr-enhanced');
            bar.classList.toggle('tt-qr-collapsed', state.qrCollapsed);
            bar.classList.toggle('tt-qr-expanded', !state.qrCollapsed);
            bar.classList.toggle('tt-qr-toggle-at-right', state.qrToggleSide === 'right');
            bar.classList.toggle('tt-qr-toggle-at-left', state.qrToggleSide === 'left');

            let toggle = qs(`#${QR_TOGGLE_ID}`, bar);
            if (!toggle) {
                toggle = createElement('button', '');
                toggle.id = QR_TOGGLE_ID;
                toggle.type = 'button';
                toggle.innerHTML = '<i class="fa-solid fa-chevron-down"></i><span class="tt-qr-count"></span>';
                toggle.addEventListener('click', (event) => {
                    event.preventDefault();
                    event.stopPropagation();
                    state.qrCollapsed = !state.qrCollapsed;
                    storage.set('tt-tools:qr-collapsed', String(state.qrCollapsed));
                    applyQrState();
                    updateToolboxQuickUi();
                });
            }
            toggle.classList.toggle('tt-qr-toggle-right', state.qrToggleSide === 'right');
            toggle.classList.toggle('tt-qr-toggle-left', state.qrToggleSide === 'left');
            if (toggle.parentElement !== bar) bar.appendChild(toggle);
            updateQrToggle(bar, toggle);
        }
        renderShortcutButtons();
        updateToolboxQuickUi();
    }

    function ensureQrBar() {
        applyQrState();
    }

    function getShortcutRecords() {
        const records = [];
        for (const record of state.managed.values()) {
            if (record.el?.isConnected) {
                records.push({
                    kind: 'float',
                    key: record.key,
                    title: record.title,
                    icon: 'fa-window-restore',
                    visible: isFloatingRecordVisible(record),
                    record,
                });
            }
        }
        return records;
    }

    function getFloatingVisualElement(record) {
        if (!record?.el) return null;
        if (record.el.id === 'th-asr-widget-v3') return record.el.querySelector('.th-asr-panel') || record.el;
        return record.el;
    }

    function getFloatingOpenElement(record) {
        if (!record?.el) return null;
        if (record.el.id === 'th-asr-widget-v3') {
            return qs('#th-asr-wand-container-v3 [data-action="open-widget-from-extensions-menu"]')
                || qs('[data-action="open-widget-from-extensions-menu"]');
        }
        return null;
    }

    function isFloatingRecordVisible(record) {
        return isElementVisible(getFloatingVisualElement(record));
    }

    function resolveFloatingRecordElement(record) {
        if (!record?.key?.startsWith('id:')) return record?.el;
        const current = qs(`#${escapeSelector(record.key.slice(3))}`);
        if (current && current !== record.el) {
            record.el = current;
            record.title = getFloatingTitle(current, record.key);
        }
        return record?.el;
    }

    function getFloatingClickTarget(element) {
        if (!element) return null;
        try {
            if (HOST.getComputedStyle?.(element)?.pointerEvents !== 'none') return element;
        } catch { /* ignore */ }
        const scope = element.shadowRoot || element;
        return scope.querySelector?.('[data-float-trigger], [aria-haspopup], button, [role="button"], a[href], [onclick]') || element;
    }

    function openFloatingShortcut(key) {
        const record = state.managed.get(key);
        if (!record) return;
        resolveFloatingRecordElement(record);
        const element = record?.el;
        if (!element?.isConnected) return;
        try {
            const className = String(element.className || '');
            if (element.id === 'wxhl-cygf-ball' && typeof HOST.WxhlCg?.open === 'function') {
                HOST.WxhlCg.open();
                return;
            }
            if (className.includes('float-btn') && typeof HOST.__WXHL_OPEN_PHONE__ === 'function') {
                HOST.__WXHL_OPEN_PHONE__();
                return;
            }
            // Phần tử chỉ bị ẩn về mặt thị giác, giữ nguyên bố cục và trình xử lý sự kiện, do đó không cần hiển thị trước vẫn có thể kích hoạt cửa sổ nổi gốc.
            getFloatingClickTarget(element)?.click();
        } catch (error) {
            console.warn('[TT Enhanced Tools] open floating window failed', error);
        }
    }

    function refreshQrToggleCounts() {
        for (const bar of qsa('#qr--bar')) {
            const toggle = qs(`#${QR_TOGGLE_ID}`, bar);
            if (toggle) updateQrToggle(bar, toggle);
        }
    }

    function renderShortcutButtons(force = false) {
        if (!state.collectShortcuts) {
            for (const container of qsa('#tt-shortcut-bar')) container.remove();
            state.lastShortcutSignature = '';
            refreshQrToggleCounts();
            return;
        }

        const bar = qs('#qr--bar');
        if (!bar) return;

        let container = qs('#tt-shortcut-bar', bar);
        let created = false;
        if (!container) {
            container = createElement('div', '');
            container.id = 'tt-shortcut-bar';
            bar.appendChild(container);
            created = true;
        }

        const records = getShortcutRecords();
        const signature = records.map(record => `${record.kind}:${record.key}:${record.title}:${record.visible}`).join('|');
        const hasSettingsButton = Boolean(container.querySelector('.tt-settings-shortcut'));
        if (!force && !created && hasSettingsButton && signature === state.lastShortcutSignature) return;
        state.lastShortcutSignature = signature;

        container.replaceChildren();
        for (const record of records) {
            const button = createElement('button', 'qr--button tt-shortcut-button');
            button.type = 'button';
            button.dataset.ttShortcutKey = record.key;
            button.dataset.ttShortcutKind = record.kind;
            button.title = `Mở [${record.title}]`;

            const icon = createElement('i', `fa-solid ${record.icon} tt-shortcut-icon`);
            const label = createElement('span', '', record.title);
            button.append(icon, label);
            button.addEventListener('click', (event) => {
                event.preventDefault();
                event.stopPropagation();
                openFloatingShortcut(record.key);
            });
            container.appendChild(button);
        }

        const settingsButton = createElement('button', 'qr--button tt-shortcut-button tt-settings-shortcut');
        settingsButton.type = 'button';
        settingsButton.title = 'Mở cài đặt Hộp công cụ nâng cao SillyTavern của Minh Thiên';
        settingsButton.innerHTML = '<i class="fa-solid fa-gear tt-shortcut-icon"></i><span>Cài đặt</span>';
        settingsButton.addEventListener('click', (event) => {
            event.preventDefault();
            event.stopPropagation();
            setPanelOpen(true);
        });
        container.appendChild(settingsButton);
        refreshQrToggleCounts();
    }

    function renderShortcutPreview() {
        const preview = qs('#tt-shortcut-preview');
        if (!preview) return;
        preview.replaceChildren();

        const records = getShortcutRecords();
        if (records.length === 0) {
            preview.appendChild(createElement('div', 'tt-float-empty', 'Chưa phát hiện cửa sổ nổi nào. Có thể nhấp vào "Làm mới thu gom" để quét lại.'));
            return;
        }

        for (const record of records) {
            const chip = createElement('span', 'tt-shortcut-chip');
            const icon = createElement('i', `fa-solid ${record.icon}`);
            const label = createElement('span', '', record.title);
            const source = createElement('small', '', 'Cửa sổ nổi');
            chip.append(icon, label, source);
            preview.appendChild(chip);
        }
    }
    function getScriptNameFromRoot(element) {
        let scriptId = '';
        let node = element;
        while (node && node !== DOC.documentElement) {
            scriptId = node.getAttribute?.('script_id') || '';
            if (scriptId) break;
            node = node.parentElement;
        }
        if (!scriptId) return '';
        for (const iframe of qsa('iframe[id^="TH-script--"]')) {
            if (!iframe.id.endsWith(scriptId)) continue;
            const tail = iframe.id.slice('TH-script--'.length);
            const separator = tail.lastIndexOf('--');
            return separator > 0 ? tail.slice(0, separator) : '';
        }
        return '';
    }

    function getFloatingTitle(element, key = '') {
        if (!element) return 'Cửa sổ nổi chưa đặt tên';
        if (key && state.customFloatNames[key]) return String(state.customFloatNames[key]).slice(0, 40);

        const id = element.id;
        if (id && FLOAT_TITLES[id]) return FLOAT_TITLES[id];

        const scriptName = getScriptNameFromRoot(element);
        if (scriptName) return scriptName.slice(0, 40);

        const explicit = element.getAttribute('data-title')
            || element.getAttribute('data-name')
            || element.getAttribute('title')
            || element.getAttribute('aria-label');
        if (explicit?.trim()) {
            const cleaned = explicit
                .trim()
                .replace(/^打开/, '')
                .split(/\s*[·•|｜;；]\s*/)[0]
                .replace(/[，,].*$/, '')
                .trim();
            if (cleaned) return cleaned.slice(0, 40);
        }

        const candidates = [
            element.querySelector(':scope > header'),
            element.querySelector(':scope > .header'),
            element.querySelector(':scope > .qr--header'),
            element.querySelector('.drag-grabber'),
            element.querySelector('[class*="title"], [class*="Title"]'),
            element.querySelector('[class*="name"], [class*="Name"]'),
            element.querySelector('h1, h2, h3, h4, h5, h6'),
        ];
        for (const candidate of candidates) {
            const text = candidate?.textContent?.replace(/\s+/g, ' ').trim();
            if (text) return text.slice(0, 40);
        }

        const ownText = element.textContent?.replace(/\s+/g, ' ').trim();
        if (ownText && ownText.length <= 50) return ownText;
        return id ? id.replace(/[-_]+/g, ' ') : (element.localName || 'Cửa sổ nổi');
    }

    function isElementVisible(element) {
        if (!element || !element.isConnected) return false;
        try {
            const style = HOST.getComputedStyle?.(element);
            if (!style || style.display === 'none' || style.visibility === 'hidden') return false;
            return element.getClientRects().length > 0;
        } catch {
            return true;
        }
    }

    function getFloatingKey(element) {
        if (element.id) return `id:${element.id}`;
        const assigned = element.getAttribute('data-tt-floating-window');
        if (assigned) return `attr:${assigned}`;
        const assignment = `tt-fw-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
        element.setAttribute('data-tt-floating-window', assignment);
        return `attr:${assignment}`;
    }

    function isCandidateElement(element) {
        if (!element || element.nodeType !== 1) return false;
        if (element === DOC.body || element === DOC.documentElement) return false;
        if (element.closest?.(`#${ROOT_ID}`)) return false;
        if (['SCRIPT', 'STYLE', 'LINK', 'META', 'TEMPLATE'].includes(element.tagName)) return false;
        if (['send_form', 'sheld', 'chat', 'options', 'movingDivs'].includes(element.id)) return false;
        if (element.id?.startsWith('tt-')) return false;
        if (element.id && /toast|popup|modal|overlay|backdrop|loader|^bg/i.test(element.id)) return false;
        if (element.matches?.('.toast, .toast-container, .popup, .modal, .overlay, .backdrop, .loader')) return false;
        return true;
    }

    function registerFloating(element, source = 'auto') {
        if (!isCandidateElement(element)) return null;
        const key = getFloatingKey(element);
        const existing = state.managed.get(key);
        if (existing) {
            existing.el = element;
            existing.source = existing.source === 'picked' ? 'picked' : source;
            existing.title = getFloatingTitle(element, key);
            return existing;
        }
        const record = {
            key,
            el: element,
            title: getFloatingTitle(element, key),
            hiddenByUs: false,
            lastVisible: false,
            manualVisible: false,
            source,
        };
        state.managed.set(key, record);
        return record;
    }

    const FLOAT_SKIP = [
        '#top-settings-holder', '#top-bar', '#send_form', '#form_sheld', '#chat', '.mes', '#movingDivs',
        '#expression-holder', '#expression-wrapper', '#visual-novel-wrapper', '.popup', 'dialog',
        '#toast-container', '.drawer-content', '#bg1', '#bg_custom', `#${ROOT_ID}`,
    ].join(', ');

    function getDocumentRoots() {
        const out = [DOC];
        const walk = (root) => {
            for (const element of root.querySelectorAll('*')) {
                if (!element.shadowRoot) continue;
                out.push(element.shadowRoot);
                walk(element.shadowRoot);
            }
        };
        walk(DOC);
        return out;
    }

    function getParentNode(node) {
        if (!node) return null;
        if (node.parentElement) return node.parentElement;
        const root = node.getRootNode?.();
        return root instanceof HOST.ShadowRoot ? root.host : null;
    }

    function isDockHidden(element) {
        return Boolean(element?.hasAttribute?.('data-tt-dock-hidden'));
    }

    function applyForcedHide(element) {
        if (!element || !isDockHidden(element)) return;
        for (const [property, value] of [['visibility', 'hidden'], ['opacity', '0'], ['pointer-events', 'none']]) {
            if (element.style.getPropertyValue(property) !== value || element.style.getPropertyPriority(property) !== 'important') {
                element.style.setProperty(property, value, 'important');
            }
        }
    }

    function stopHideObserver(element) {
        const observer = state.hideObservers.get(element);
        if (observer) {
            observer.disconnect();
            state.hideObservers.delete(element);
        }
    }

    function ensureHideObserver(element) {
        if (!HOST.MutationObserver || state.hideObservers.has(element)) return;
        const observer = new HOST.MutationObserver(() => applyForcedHide(element));
        observer.observe(element, { attributes: true, attributeFilter: ['style'] });
        state.hideObservers.set(element, observer);
    }

    function hideFloatingElement(element) {
        if (!element || isDockHidden(element)) return;
        const saved = {};
        for (const property of ['display', 'visibility', 'opacity', 'pointer-events']) {
            saved[property] = [element.style.getPropertyValue(property), element.style.getPropertyPriority(property)];
        }
        element.dataset.ttDockStyles = JSON.stringify(saved);
        element.setAttribute('data-tt-dock-hidden', '1');
        applyForcedHide(element);
        ensureHideObserver(element);
    }

    function unhideFloatingElement(element) {
        if (!element || !isDockHidden(element)) return;
        stopHideObserver(element);
        let saved = {};
        try { saved = JSON.parse(element.dataset.ttDockStyles || '{}'); } catch { /* ignore */ }
        delete element.dataset.ttDockStyles;
        element.removeAttribute('data-tt-dock-hidden');
        for (const property of ['display', 'visibility', 'opacity', 'pointer-events']) {
            const [value, priority] = saved[property] || ['', ''];
            if (value) element.style.setProperty(property, value, priority || '');
            else element.style.removeProperty(property);
        }
    }

    function unionRect(element) {
        const rect = element.getBoundingClientRect();
        let left = rect.left;
        let top = rect.top;
        let right = rect.right;
        let bottom = rect.bottom;
        let count = 0;
        for (const child of element.querySelectorAll('*')) {
            if (++count > 300) break;
            const childRect = child.getBoundingClientRect();
            if (!childRect.width || !childRect.height) continue;
            const style = HOST.getComputedStyle?.(child);
            if (style?.visibility === 'hidden' || Number(style?.opacity) === 0) continue;
            left = Math.min(left, childRect.left);
            top = Math.min(top, childRect.top);
            right = Math.max(right, childRect.right);
            bottom = Math.max(bottom, childRect.bottom);
        }
        return { left, top, width: right - left, height: bottom - top };
    }

    function measureFloatingElement(element) {
        const wasHidden = isDockHidden(element);
        if (wasHidden) unhideFloatingElement(element);
        const live = HOST.getComputedStyle?.(element);
        const measurement = {
            position: live?.position,
            pointerEvents: live?.pointerEvents,
            cursor: live?.cursor,
            visibility: live?.visibility,
            display: live?.display,
            opacity: live?.opacity,
            zIndex: live?.zIndex,
            rect: element.getBoundingClientRect(),
        };
        if (live?.pointerEvents === 'none') measurement.unionRect = unionRect(element);
        if (wasHidden) hideFloatingElement(element);
        return measurement;
    }

    const isSmallRect = rect => rect.width >= 16 && rect.height >= 16
        && rect.width <= (HOST.innerWidth || DOC.documentElement.clientWidth) * 0.5
        && rect.height <= (HOST.innerHeight || DOC.documentElement.clientHeight) * 0.5;
    const isFullscreenRect = rect => rect.width >= (HOST.innerWidth || DOC.documentElement.clientWidth) * 0.7
        && rect.height >= (HOST.innerHeight || DOC.documentElement.clientHeight) * 0.7;
    const isShownMeasurement = measurement => {
        if (measurement.display === 'none' || measurement.visibility === 'hidden') return false;
        if (measurement.opacity === '' || measurement.opacity == null) return true;
        const opacity = Number(measurement.opacity);
        return !Number.isFinite(opacity) || opacity > 0;
    };

    function isSkippedFloatingElement(element) {
        if (element.matches?.('[class*="toast"], [class*="notice-bubble"], [class*="notification"], [role="alert"]')) return true;
        for (let node = element; node; node = getParentNode(node)) {
            if (node.matches?.(FLOAT_SKIP)) return true;
        }
        return false;
    }

    function isInsideLargePanel(element, layer) {
        for (let node = getParentNode(element); node && node !== layer && node !== layer?.shadowRoot?.host; node = getParentNode(node)) {
            const rect = node.getBoundingClientRect();
            if (rect.width > (HOST.innerWidth || DOC.documentElement.clientWidth) * 0.5
                || rect.height > (HOST.innerHeight || DOC.documentElement.clientHeight) * 0.5) return true;
        }
        return false;
    }

    function getFixedFloatingCandidates() {
        const out = [];
        for (const root of getDocumentRoots()) {
            const start = root === DOC ? DOC.body : root;
            if (!start) continue;
            try {
                const walker = DOC.createTreeWalker(start, HOST.NodeFilter?.SHOW_ELEMENT ?? 1, {
                    acceptNode(node) {
                        if (node.matches?.(FLOAT_SKIP)) return HOST.NodeFilter?.FILTER_REJECT ?? 2;
                        if (!isDockHidden(node) && node.getClientRects().length === 0
                            && HOST.getComputedStyle?.(node)?.display !== 'contents') {
                            return HOST.NodeFilter?.FILTER_REJECT ?? 2;
                        }
                        return HOST.NodeFilter?.FILTER_ACCEPT ?? 1;
                    },
                });
                for (let node = walker.nextNode(); node; node = walker.nextNode()) {
                    if (isDockHidden(node) || HOST.getComputedStyle?.(node)?.position === 'fixed') out.push(node);
                }
            } catch { /* ignore broken subtree */ }
        }
        return out;
    }

    function isFloatingTriggerElement(element, measurement) {
        if (element.matches?.('button, a[href], [role="button"], [aria-haspopup], [onclick], [title], [class*="float-btn"], [class*="fab"], [class*="launch"]')) return true;
        return measurement.cursor === 'grab' || measurement.cursor === 'move';
    }

    function autoDetectFloatingWindows() {
        const found = new Set();
        for (const element of getFixedFloatingCandidates()) {
            if (isSkippedFloatingElement(element)) continue;
            const measurement = measureFloatingElement(element);
            if (measurement.position !== 'fixed' || !isShownMeasurement(measurement)) continue;

            if (measurement.pointerEvents !== 'none') {
                if (isSmallRect(measurement.rect) && isFloatingTriggerElement(element, measurement)) found.add(element);
                continue;
            }

            if (!isFullscreenRect(measurement.rect)) {
                if (measurement.unionRect && isSmallRect(measurement.unionRect)) found.add(element);
                continue;
            }

            const inner = [
                ...element.querySelectorAll('*'),
                ...(element.shadowRoot ? element.shadowRoot.querySelectorAll('*') : []),
            ];
            for (const child of inner) {
                const childMeasurement = measureFloatingElement(child);
                if (childMeasurement.pointerEvents === 'none'
                    || !isShownMeasurement(childMeasurement)
                    || !isSmallRect(childMeasurement.rect)) continue;
                if (childMeasurement.position !== 'absolute' && childMeasurement.position !== 'fixed') continue;
                if (isInsideLargePanel(child, element)) continue;
                if (!isFloatingTriggerElement(child, childMeasurement)) continue;
                found.add(child);
            }
        }
        return Array.from(found);
    }

    function pruneNestedFloatingRecords() {
        const records = Array.from(state.managed.values()).filter(record => record.el?.isConnected);
        for (const child of records) {
            for (const parent of records) {
                if (child === parent || child.el === parent.el) continue;
                if (parent.el.contains(child.el) || parent.el.shadowRoot?.contains?.(child.el)) {
                    if (child.source !== 'picked') {
                        state.managed.delete(child.key);
                        break;
                    }
                }
            }
        }
    }
    function scanFloatingWindows() {
        if (state.destroyed) return;

        for (const element of autoDetectFloatingWindows()) registerFloating(element, 'auto');
        for (const selector of state.customSelectors) {
            try {
                for (const element of qsa(selector)) {
                    if (!isCandidateElement(element)) continue;
                    const rect = element.getBoundingClientRect();
                    const viewportWidth = HOST.innerWidth || DOC.documentElement.clientWidth || 0;
                    const viewportHeight = HOST.innerHeight || DOC.documentElement.clientHeight || 0;
                    const isFullScreenShell = viewportWidth > 0 && viewportHeight > 0
                        && rect.width >= viewportWidth * 0.9
                        && rect.height >= viewportHeight * 0.9;
                    if (isFullScreenShell && !element.matches('#movingDivs > *, #qr--popout, #th-asr-widget-v3')) continue;
                    registerFloating(element, 'picked');
                }
            } catch { /* invalid/stale selector */ }
        }
        pruneNestedFloatingRecords();

        for (const [key, record] of state.managed) {
            if (!record.el?.isConnected) {
                record.disconnected = true;
            } else {
                record.disconnected = false;
                record.title = getFloatingTitle(record.el, record.key);
                record.lastVisible = isFloatingRecordVisible(record);
            }
            if (record.disconnected && record.source !== 'picked') {
                state.managed.delete(key);
            }
        }

        if (state.autoCollect) {
            if (!state.autoCollectBaseline) {
                state.autoCollectBaseline = new Set(state.managed.keys());
            } else {
                for (const [key, record] of state.managed) {
                    if (!state.autoCollectBaseline.has(key) && record.el?.isConnected && isFloatingRecordVisible(record)) {
                        state.autoCollectBaseline.add(key);
                        setFloatingHidden(record, true);
                    }
                }
            }
        }

        // Sau khi nhận diện thành công, mặc định thu gọn lối vào cửa sổ nổi gốc; trang cài đặt có thể khôi phục thủ công một lối vào nào đó và duy trì hiển thị.
        for (const record of state.managed.values()) {
            if (!record.el?.isConnected) continue;
            if (record.manualVisible) {
                if (record.hiddenByUs) setFloatingHidden(record, false);
                continue;
            }
            if (!record.hiddenByUs) setFloatingHidden(record, true);
        }

        updateFloatingCount();
        renderFloatingList();
        renderShortcutButtons();
        renderShortcutPreview();
    }

    function setFloatingHidden(record, hidden) {
        if (!record?.el?.isConnected) return;
        const element = record.el;
        if (hidden) {
            record.hiddenByUs = true;
            record.lastVisible = false;
            element.classList.add('tt-force-hidden');
            hideFloatingElement(element);
        } else if (record.hiddenByUs) {
            record.hiddenByUs = false;
            record.lastVisible = true;
            element.classList.remove('tt-force-hidden');
            unhideFloatingElement(element);
        }
    }

    function updateFloatingCount() {
        const visible = Array.from(state.managed.values()).filter(record => isFloatingRecordVisible(record)).length;
        state.lastFloatingCount = visible;
        const tabCount = qs('#tt-floating-count');
        if (tabCount) tabCount.textContent = String(visible);
        const badge = qs('#tt-toolbox-launcher-badge');
        if (badge) {
            badge.textContent = String(visible);
            badge.style.display = visible > 0 ? 'block' : 'none';
        }
    }
    function renameFloatingWindow(key) {
        const record = state.managed.get(key);
        if (!record) return;
        const promptFn = HOST.prompt || window.prompt;
        if (typeof promptFn !== 'function') {
            showToast('info', 'Môi trường hiện tại không hỗ trợ hộp nhập liệu, không thể đổi tên.');
            return;
        }
        const nextName = promptFn.call(HOST, 'Đặt tên nút tắt cho cửa sổ nổi này:', record.title || '');
        if (nextName === null || !String(nextName).trim()) return;
        const name = String(nextName).trim().slice(0, 40);
        state.customFloatNames[key] = name;
        storage.set('tt-tools:custom-float-names', JSON.stringify(state.customFloatNames));
        record.title = name;
        renderFloatingList(true);
        renderShortcutButtons(true);
        renderShortcutPreview();
    }

    function renderFloatingList(force = false) {
        const list = qs('#tt-floating-list');
        if (!list) return;

        const records = Array.from(state.managed.values())
            .filter(record => record.el?.isConnected)
            .sort((a, b) => String(a.title).localeCompare(String(b.title), 'zh-CN'));

        const signature = records.map(record => `${record.key}:${isFloatingRecordVisible(record)}:${record.hiddenByUs}:${record.manualVisible}:${record.disconnected}`).join('|');
        if (!force && signature === state.lastFloatSignature) return;
        state.lastFloatSignature = signature;

        list.replaceChildren();
        if (records.length === 0) {
            list.appendChild(createElement('div', 'tt-float-empty', 'Chưa phát hiện cửa sổ nổi nào. Có thể nhấp vào "Thu gom cửa sổ nổi" để thêm thủ công.'));
            return;
        }

        for (const record of records) {
            const item = createElement('div', 'tt-float-item');
            const status = createElement('span', `tt-float-status${isFloatingRecordVisible(record) ? ' tt-visible' : ''}`);
            const name = createElement('span', 'tt-float-name', record.title || 'Cửa sổ nổi chưa đặt tên');
            const stateText = record.disconnected ? 'Đã xóa' : (record.hiddenByUs ? 'Đã ẩn' : 'Đã khôi phục');
            name.appendChild(createElement('small', '', stateText));

            const actions = createElement('div', 'tt-float-actions');
            const toggle = createElement('button', 'tt-toolbox-icon-btn');
            toggle.type = 'button';
            toggle.dataset.ttFloatAction = 'visibility';
            toggle.dataset.ttFloatKey = record.key;
            toggle.title = record.hiddenByUs ? 'Khôi phục cửa sổ nổi này' : 'Ẩn lại cửa sổ nổi này';
            toggle.innerHTML = `<i class="fa-solid ${record.hiddenByUs ? 'fa-eye' : 'fa-eye-slash'}"></i>`;
            toggle.disabled = !record.el?.isConnected;

            const rename = createElement('button', 'tt-toolbox-icon-btn');
            rename.type = 'button';
            rename.dataset.ttFloatAction = 'rename';
            rename.dataset.ttFloatKey = record.key;
            rename.title = 'Đổi tên nút tắt';
            rename.innerHTML = '<i class="fa-solid fa-pen"></i>';

            const locate = createElement('button', 'tt-toolbox-icon-btn');
            locate.type = 'button';
            locate.dataset.ttFloatAction = 'locate';
            locate.dataset.ttFloatKey = record.key;
            locate.title = 'Định vị/Làm nổi bật cửa sổ nổi này';
            locate.innerHTML = '<i class="fa-solid fa-crosshairs"></i>';
            locate.disabled = !record.el?.isConnected;

            actions.append(toggle, rename, locate);
            item.append(status, name, actions);
            list.appendChild(item);
        }
    }
    function locateFloatingWindow(key) {
        const record = state.managed.get(key);
        if (!record?.el?.isConnected) return;
        record.manualVisible = true;
        if (!isFloatingRecordVisible(record)) setFloatingHidden(record, false);
        record.el.classList.add('tt-fw-flash');
        setTimeout(() => record.el?.classList.remove('tt-fw-flash'), 1600);
        try { record.el.scrollIntoView?.({ block: 'nearest', inline: 'nearest', behavior: 'smooth' }); } catch { /* ignore */ }
        renderFloatingList(true);
    }

    function hideAllFloatingWindows() {
        scanFloatingWindows();
        let count = 0;
        for (const record of state.managed.values()) {
            record.manualVisible = false;
            if (isElementVisible(record.el)) {
                setFloatingHidden(record, true);
                count += 1;
            }
        }
        updateFloatingCount();
        renderFloatingList(true);
        showToast('info', count > 0 ? `Đã thu gọn ${count} cửa sổ nổi, có thể mở rộng lại từ tab "Cửa sổ nổi".` : 'Hiện không có cửa sổ nổi nào hiển thị.');
    }

    function showAllFloatingWindows() {
        let count = 0;
        for (const record of state.managed.values()) {
            record.manualVisible = true;
            if (record.hiddenByUs) {
                setFloatingHidden(record, false);
                count += 1;
            }
        }
        updateFloatingCount();
        renderFloatingList(true);
        showToast('info', count > 0 ? `Đã mở rộng ${count} cửa sổ nổi được hộp công cụ thu gom.` : 'Không có cửa sổ nổi nào được hộp công cụ thu gom.');
    }

    function beginPickFloatingWindow() {
        if (state.pickMode) return;
        state.pickMode = true;
        DOC.body.classList.add('tt-fw-pick-mode');

        const hint = createElement('div', '');
        hint.id = 'tt-pick-hint';
        hint.innerHTML = '<span>Nhấp vào cửa sổ nổi cần thu gom; Nhấn Esc để hủy</span><button type="button">Hủy</button>';
        DOC.body.appendChild(hint);

        const cancel = () => {
            if (!state.pickMode) return;
            state.pickMode = false;
            DOC.body.classList.remove('tt-fw-pick-mode');
            hint.remove();
            DOC.removeEventListener('click', onClick, true);
            DOC.removeEventListener('keydown', onKeyDown, true);
            state.pickCleanup = null;
        };
        state.pickCleanup = cancel;

        const onKeyDown = (event) => {
            if (event.key === 'Escape') {
                event.preventDefault();
                cancel();
            }
        };

        const onClick = (event) => {
            if (event.target?.closest?.('#tt-pick-hint')) return;
            event.preventDefault();
            event.stopPropagation();

            let target = event.target;
            while (target && target !== DOC.body) {
                if (isCandidateElement(target) && target.getBoundingClientRect) {
                    const rect = target.getBoundingClientRect();
                    if (rect.width >= 60 && rect.height >= 35) break;
                }
                target = target.parentElement;
            }

            if (!target || target === DOC.body || target.closest?.(`#${ROOT_ID}`)) {
                showToast('info', 'Đây không phải là cửa sổ nổi có thể thu gom, vui lòng thử lại với phần tử khác.');
                return;
            }

            const selector = getCssPath(target);
            if (selector && !state.customSelectors.includes(selector)) {
                state.customSelectors.push(selector);
                storage.set('tt-tools:custom-float-selectors', JSON.stringify(state.customSelectors));
            }
            const record = registerFloating(target, 'picked');
            if (record) {
                record.disconnected = false;
                showToast('info', `Đã thu gom cửa sổ nổi: ${record.title}`);
            }
            cancel();
            renderFloatingList(true);
            updateFloatingCount();
        };

        hint.querySelector('button')?.addEventListener('click', (event) => {
            event.preventDefault();
            event.stopPropagation();
            cancel();
        });
        DOC.addEventListener('click', onClick, true);
        DOC.addEventListener('keydown', onKeyDown, true);
    }
    function getPanelElement() {
        return qs('#tt-toolbox-panel');
    }

    function setPanelOpen(open) {
        const panel = getPanelElement();
        const launcher = qs('#tt-toolbox-launcher');
        const overlay = qs('#tt-toolbox-overlay');
        if (!panel) return;
        state.panelOpen = Boolean(open);
        panel.classList.toggle('tt-hidden', !state.panelOpen);
        overlay?.classList.toggle('tt-visible', state.panelOpen);
        launcher?.setAttribute('aria-expanded', String(state.panelOpen));
        if (state.panelOpen) {
            fitPanelIntoViewport(panel);
            setTimeout(() => fitPanelIntoViewport(panel), 0);
            scanFloatingWindows();
            renderFloatingList(true);
            renderShortcutPreview();
            updateToolboxQuickUi();
