    function loadPanelPosition() {
        const panel = getPanelElement();
        if (!panel) return;
        const position = readJson('tt-tools:panel-position-v2', null);
        if (position && Number.isFinite(position.left) && Number.isFinite(position.top)) {
            panel.style.left = `${position.left}px`;
            panel.style.top = `${position.top}px`;
            panel.style.right = 'auto';
            panel.style.bottom = 'auto';
            panel.style.transform = 'none';
        }
    }

    function getViewportBounds() {
        const viewport = HOST.visualViewport;
        const width = viewport?.width || HOST.innerWidth || DOC.documentElement.clientWidth || 0;
        const height = viewport?.height || HOST.innerHeight || DOC.documentElement.clientHeight || 0;
        const left = viewport?.offsetLeft || 0;
        const top = viewport?.offsetTop || 0;
        return { left, top, right: left + width, bottom: top + height, width, height };
    }

    function fitPanelIntoViewport(panel = getPanelElement()) {
        if (!panel || panel.classList.contains('tt-hidden')) return;
        const margin = 8;
        const view = getViewportBounds();
        const availableWidth = Math.max(160, view.width - margin * 2);
        const availableHeight = Math.max(120, view.height - margin * 2);
        panel.style.maxWidth = `${availableWidth}px`;
        panel.style.maxHeight = `${availableHeight}px`;

        const rect = panel.getBoundingClientRect();
        const width = Math.min(rect.width, availableWidth);
        const height = Math.min(rect.height, availableHeight);
        let left = rect.left;
        let top = rect.top;

        if (rect.right > view.right - margin || rect.left < view.left + margin) {
            left = Math.min(Math.max(rect.left, view.left + margin), view.right - width - margin);
        }
        if (rect.bottom > view.bottom - margin || rect.top < view.top + margin) {
            top = Math.min(Math.max(rect.top, view.top + margin), view.bottom - height - margin);
        }
        if (left !== rect.left || top !== rect.top) {
            panel.style.left = `${Math.max(view.left + margin, left)}px`;
            panel.style.top = `${Math.max(view.top + margin, top)}px`;
            panel.style.right = 'auto';
            panel.style.bottom = 'auto';
            panel.style.transform = 'none';
        }
    }

    function clampPanelPosition(panel, left, top) {
        const margin = 8;
        const view = getViewportBounds();
        const maxLeft = Math.max(view.left + margin, view.right - panel.offsetWidth - margin);
        const maxTop = Math.max(view.top + margin, view.bottom - panel.offsetHeight - margin);
        return {
            left: Math.min(Math.max(view.left + margin, left), maxLeft),
            top: Math.min(Math.max(view.top + margin, top), maxTop),
        };
    }

    function setupPanelDrag() {
        const panel = getPanelElement();
        const handle = qs('#tt-toolbox-header');
        if (!panel || !handle) return;

        let dragState = null;
        handle.addEventListener('pointerdown', (event) => {
            if (event.button !== 0 || event.target.closest('button')) return;
            const rect = panel.getBoundingClientRect();
            dragState = {
                offsetX: event.clientX - rect.left,
                offsetY: event.clientY - rect.top,
                pointerId: event.pointerId,
            };
            panel.style.left = `${rect.left}px`;
            panel.style.top = `${rect.top}px`;
            panel.style.right = 'auto';
            panel.style.bottom = 'auto';
            panel.style.transform = 'none';
            try { handle.setPointerCapture(event.pointerId); } catch { /* ignore */ }
        });
        handle.addEventListener('pointermove', (event) => {
            if (!dragState || event.pointerId !== dragState.pointerId) return;
            const next = clampPanelPosition(panel, event.clientX - dragState.offsetX, event.clientY - dragState.offsetY);
            panel.style.left = `${next.left}px`;
            panel.style.top = `${next.top}px`;
        });
        const endDrag = (event) => {
            if (!dragState) return;
            dragState = null;
            const rect = panel.getBoundingClientRect();
            storage.set('tt-tools:panel-position-v2', JSON.stringify({ left: rect.left, top: rect.top }));
        };
        handle.addEventListener('pointerup', endDrag);
        handle.addEventListener('pointercancel', endDrag);
    }
