    function isPopupShown(element) {
        if (!element?.isConnected) return false;
        if (element.open === false) return false;
        const style = HOST.getComputedStyle?.(element);
        return style && style.display !== 'none' && style.visibility !== 'hidden' && Number(style.opacity || 1) > 0;
    }

    function shouldAutoConfirmImportPopup(text) {
        const normalized = String(text || '').replace(/\s+/g, ' ').trim();
        if (!normalized) return false;
        const scriptPopup = /(?:酒馆助手|Tavern\s*Helper)[\s\S]*(?:嵌入式脚本|embedded\s+script)|(?:嵌入式脚本|embedded\s+script)[\s\S]*(?:酒馆助手|Tavern\s*Helper)/i.test(normalized);
        const regexPopup = /(?:内置|内嵌|嵌入)[\s\S]*正则脚本|embedded\s+regex\s+script|regex\s+script\(s\)/i.test(normalized)
            && /(?:启用|允许|使用它们|allow|enable|use them)/i.test(normalized);
        return scriptPopup || regexPopup;
    }

    function scanAutoConfirmPopups() {
        if (!state.autoConfirmImports || state.destroyed) return;
        for (const popup of qsa('dialog.popup, .TH-popup .popup')) {
            if (popup.dataset.ttAutoConfirmHandled === '1' || !isPopupShown(popup)) continue;
            if (!shouldAutoConfirmImportPopup(popup.innerText)) continue;
            const okButton = popup.querySelector('.popup-button-ok')
                || Array.from(popup.querySelectorAll('button, .menu_button')).find(button => /^(确认|确定|是|允许|yes|ok|allow)$/i.test((button.innerText || '').trim()));
            if (!okButton || state.autoConfirmHandled.has(okButton)) continue;
            state.autoConfirmHandled.add(okButton);
            popup.dataset.ttAutoConfirmHandled = '1';
            setTimeout(() => {
                if (okButton.isConnected) okButton.click();
            }, 40);
        }
    }

    function debugGeneration(entry) {
        try {
            state.generationDebug.push({ t: Date.now(), ...entry });
            if (state.generationDebug.length > 200) state.generationDebug.splice(0, state.generationDebug.length - 200);
        } catch { /* ignore */ }
    }

    function isRetryableGenerationError(message, title) {
        if (!state.autoRetryOnError || state.destroyed) return false;
        if (!state.generationActive && DOC.body?.dataset?.generating !== 'true') return false;
        const combined = `${String(title ?? '')}\n${String(message ?? '')}`;
        const retryable = /API\s*Error|Text generation error|API\s*错误|接口错误|请求失败|网络错误|连接失败|Failed to fetch|NetworkError|Load failed|timed?\s*out|timeout|rate limit|too many requests|HTTP\s*[45]\d\d|status\s*[45]\d\d|request failed|request error/i.test(combined);
        if (retryable) state.lastGenerationErrorAt = Date.now();
        return retryable;
    }

    function cancelScheduledGenerationRetry() {
        if (state.retryState.timer) clearTimeout(state.retryState.timer);
        state.retryState.timer = null;
        state.retryState.scheduled = false;
    }

    function resetGenerationRetryState() {
        cancelScheduledGenerationRetry();
        state.retryState.attempts = 0;
        state.retryState.expected = false;
    }

    function scheduleGenerationRetry() {
        if (!state.autoRetryOnError || state.retryState.scheduled) return;
        if (state.retryState.attempts >= state.retryMaxAttempts) {
            showToast('error', `Tự động thử lại khi API báo lỗi đã đạt giới hạn tối đa (${state.retryMaxAttempts} lần).`);
            return;
        }

        state.retryState.attempts += 1;
        state.retryState.scheduled = true;
        const delayMs = Math.round(state.retryIntervalSeconds * 1000);
        showToast('info', `Tạo thất bại, sẽ thử lại lần thứ ${state.retryState.attempts}/${state.retryMaxAttempts} sau ${state.retryIntervalSeconds} giây.`);

        state.retryState.timer = setTimeout(() => {
            state.retryState.timer = null;
            state.retryState.scheduled = false;
            state.retryState.expected = true;
            void doRegenerate();
        }, delayMs);
    }

    async function requestDesktopNotificationPermission() {
        const NotificationCtor = HOST.Notification || window.Notification;
        if (!NotificationCtor) {
            showToast('info', 'Môi trường hiện tại không hỗ trợ thông báo trên màn hình.');
            return false;
        }
        if (NotificationCtor.permission === 'granted') return true;
        if (NotificationCtor.permission === 'denied') {
            showToast('info', 'Quyền thông báo trên màn hình đã bị từ chối, vui lòng cấp phép thủ công trong trình duyệt hoặc hệ thống.');
            return false;
        }
        try {
            const permission = await NotificationCtor.requestPermission();
            return permission === 'granted';
        } catch (error) {
            console.warn('[TT Enhanced Tools] desktop notification permission failed', error);
            return false;
        }
    }

    function showDesktopNotification() {
        if (!state.desktopNotifyOnDone) return;
        const NotificationCtor = HOST.Notification || window.Notification;
        if (!NotificationCtor) return;
        const show = () => {
            try {
                if (NotificationCtor.permission === 'granted') {
                    new NotificationCtor('Tavern Helper', {
                        body: 'Đã hoàn tất tạo nội dung',
                        tag: 'tt-generation-complete',
                        renotify: true,
                    });
                }
            } catch (error) {
                console.warn('[TT Enhanced Tools] desktop notification failed', error);
            }
        };
        if (NotificationCtor.permission === 'granted') {
            show();
        } else if (NotificationCtor.permission === 'default') {
            void NotificationCtor.requestPermission().then(permission => {
                if (permission === 'granted') show();
            }).catch(() => { /* ignore */ });
        }
    }

    function cancelScrollCorrection() {
        const correction = state.scrollCorrection;
        if (!correction) return;
        state.scrollCorrection = null;
        if (correction.timer) clearTimeout(correction.timer);
        for (const [element, event, handler] of correction.listeners || []) {
            try { element.removeEventListener(event, handler); } catch { /* ignore */ }
        }
    }

    function scrollToLatestGeneratedMessage(messageId) {
        if (!state.scrollToLatestOnDone) return;
        cancelScrollCorrection();

        const chat = qs('#chat');
        const startedAt = Date.now();
        let lastSignature = '';
        let lastSignatureAt = startedAt;
        let ticks = 0;
        let timer = null;
        const listeners = [];
        const correction = { timer: null, listeners };
        state.scrollCorrection = correction;

        const cleanup = () => {
            if (timer) clearTimeout(timer);
            if (state.scrollCorrection === correction) state.scrollCorrection = null;
            for (const [element, event, handler] of listeners) {
                try { element.removeEventListener(event, handler); } catch { /* ignore */ }
            }
            listeners.length = 0;
        };

        const cancelOnUserIntent = () => cleanup();
        if (chat) {
            for (const event of ['wheel', 'touchstart', 'pointerdown']) {
                const handler = () => cancelOnUserIntent();
                chat.addEventListener(event, handler, { passive: true });
                listeners.push([chat, event, handler]);
            }
        }

        const tick = () => {
            if (state.destroyed || state.scrollCorrection !== correction) return cleanup();
            ticks += 1;

            const context = getContext();
            const chatData = context?.chat;
            const latestId = Array.isArray(chatData) && chatData.length ? chatData.length - 1 : null;
            const latestMessage = latestId !== null ? chatData[latestId] : null;
            if (!latestMessage || latestMessage.is_user) {
                if (Date.now() - startedAt < 10000 && ticks < 50) timer = setTimeout(tick, 250);
                else cleanup();
                return;
            }

            const numericId = latestId ?? Number(messageId);
            const target = Number.isFinite(numericId)
                ? qs(`#chat .mes[mesid="${numericId}"]`) || qs('#chat .mes.last_mes')
                : qs('#chat .mes.last_mes');
            if (!target) {
                if (Date.now() - startedAt < 10000 && ticks < 50) timer = setTimeout(tick, 250);
                else cleanup();
                return;
            }

            const now = Date.now();
            const signature = [
                latestId,
                String(latestMessage.mes ?? latestMessage.content ?? '').length,
                String(target.innerText ?? target.textContent ?? '').length,
                target.scrollHeight,
                target.offsetHeight,
                chat?.scrollHeight,
            ].join('|');
            if (signature !== lastSignature) {
                lastSignature = signature;
                lastSignatureAt = now;
            }

            try {
                if (chat) {
                    const chatRect = chat.getBoundingClientRect();
                    const targetRect = target.getBoundingClientRect();
                    const expectedTop = chat.scrollTop + targetRect.top - chatRect.top;
                    if (Math.abs(chat.scrollTop - expectedTop) > 8) {
                        chat.scrollTo?.({ top: expectedTop, behavior: 'auto' });
                    }
                } else {
                    target.scrollIntoView({ block: 'start', inline: 'nearest', behavior: 'auto' });
                }
            } catch { /* ignore */ }

            const elapsed = now - startedAt;
            const shouldContinue = elapsed < 10000;
            if (shouldContinue && ticks < 50) {
                timer = setTimeout(tick, 250);
                correction.timer = timer;
            } else {
                cleanup();
            }
        };

        tick();
    }

    function runPostGenerationActions(messageId, type) {
        if (state.postEffectGeneration === state.generationSequence) return;
        if (type === 'first_message' || type === 'impersonate' || type === 'quiet') return;
        state.postEffectGeneration = state.generationSequence;
        debugGeneration({ kind: 'run', seq: state.generationSequence, messageId, type });

        resetGenerationRetryState();
        scrollToLatestGeneratedMessage(messageId);
        if (state.vibrateOnDone) {
            try { HOST.navigator?.vibrate?.([160, 70, 160]); } catch { /* ignore */ }
        }
        if (state.desktopNotifyOnDone) showDesktopNotification();
    }

    function schedulePostGenerationCompletionCheck(delay = 120, attempt = 0) {
        if (state.generationWaitTimer) clearTimeout(state.generationWaitTimer);
        state.generationWaitTimer = setTimeout(() => {
            state.generationWaitTimer = null;
            const pending = state.pendingGenerationResult;
            debugGeneration({ kind: 'check', attempt, seq: state.generationSequence, endedSeq: state.generationEndedForSequence, pending: pending ? { id: pending.messageId, seq: pending.sequence, type: pending.type } : null, active: state.generationActive, lastRenderAt: state.lastMessageRenderAt, endedAt: state.generationEndedAt });
            if (!pending || pending.sequence !== state.generationSequence) return;
            if (state.postEffectGeneration === pending.sequence) return;

            if (state.generationEndedForSequence !== pending.sequence) {
                if (attempt < 80) schedulePostGenerationCompletionCheck(120, attempt + 1);
                return;
            }

            const bodyGenerating = DOC.body?.dataset?.generating === 'true' || isGenerating();
            if (bodyGenerating && attempt < 80) {
                schedulePostGenerationCompletionCheck(120, attempt + 1);
                return;
            }
            if (bodyGenerating) return;

            if (state.lastGenerationErrorAt >= state.lastGenerationStartedAt) {
                state.pendingGenerationResult = null;
                return;
            }

            // Chờ sự kiện render cuối cùng và kích thước DOM ổn định, tránh việc nhảy trước khi tin nhắn vẫn đang dàn lại trang hoặc tự động cuộn xuống đáy.
            const now = Date.now();
            if (now - state.generationEndedAt < 120) {
                schedulePostGenerationCompletionCheck(120, attempt + 1);
                return;
            }
            if (state.lastMessageRenderAt && now - state.lastMessageRenderAt < 120) {
                schedulePostGenerationCompletionCheck(120, attempt + 1);
                return;
            }

            const context = getContext();
            const chat = context?.chat;
            const latestId = Array.isArray(chat) && chat.length ? chat.length - 1 : null;
            const latestMessage = latestId !== null ? chat[latestId] : null;
            const latestElement = latestId !== null ? qs(`#chat .mes[mesid="${latestId}"]`) : null;
            const latestText = String(latestMessage?.mes ?? latestMessage?.content ?? '').trim();
            const renderedText = String(latestElement?.innerText ?? latestElement?.textContent ?? '').trim();

            if (!latestMessage || latestMessage.is_user || !latestElement || !latestText || !renderedText) {
                if (attempt < 80) schedulePostGenerationCompletionCheck(120, attempt + 1);
                return;
            }

            const signature = [latestId, latestText.length, renderedText.length, latestElement.scrollHeight, latestElement.offsetHeight].join('|');
            if (state.pendingRenderSignature === signature) state.pendingRenderStableCount += 1;
            else {
                state.pendingRenderSignature = signature;
                state.pendingRenderStableCount = 1;
            }
            if (state.pendingRenderStableCount < 2) {
                schedulePostGenerationCompletionCheck(120, attempt + 1);
                return;
            }

            state.pendingGenerationResult = null;
            state.pendingRenderSignature = '';
            state.pendingRenderStableCount = 0;
            runPostGenerationActions(latestId, pending.type);
        }, delay);
    }

    function setupGenerationWatchers() {
        if (state.generationWatchers.length) return;
        const context = getContext();
        const source = context?.eventSource;
        const types = context?.eventTypes;
        if (!source || !types) return;

        const add = (event, handler) => {
            if (!event) return;
            source.on(event, handler);
            state.generationWatchers.push({ source, event, handler });
        };

        add(types.GENERATION_STARTED, (type, _options, dryRun) => {
            if (dryRun) return;
            if (!['normal', 'regenerate', 'swipe', 'continue'].includes(type)) return;
            if (state.generationWaitTimer) clearTimeout(state.generationWaitTimer);
            state.generationWaitTimer = null;
            state.pendingGenerationResult = null;
            state.pendingRenderSignature = '';
            state.pendingRenderStableCount = 0;
            state.lastGenerationStartedAt = Date.now();
            state.lastGenerationErrorAt = 0;
            state.generationEndedForSequence = 0;
            state.generationEndedAt = 0;
            state.lastMessageRenderAt = 0;
            state.chatLengthAtGenerationStart = getContext()?.chat?.length ?? 0;
            cancelScrollCorrection();
            state.generationActive = true;
            state.activeGenerationType = type;
            state.generationSequence += 1;
            debugGeneration({ kind: 'started', type, seq: state.generationSequence, chatLen: getContext()?.chat?.length });
            if (!state.retryState.expected) state.retryState.attempts = 0;
            state.retryState.expected = false;
        });

        const acceptLatestMessageEvent = (messageId, type) => {
            const context = getContext();
            const chat = context?.chat;
            const latestId = Array.isArray(chat) && chat.length ? chat.length - 1 : null;
            const numericId = Number(messageId);
            if (latestId === null) return;
            if (Number.isFinite(numericId) && numericId !== latestId) return;
            if (!state.generationActive && state.generationEndedForSequence !== state.generationSequence) return;
            if (type === 'first_message' || type === 'impersonate' || type === 'quiet') return;
            state.pendingGenerationResult = {
                messageId: latestId,
                type: type || state.activeGenerationType,
                sequence: state.generationSequence,
            };
            debugGeneration({ kind: 'message', messageId, latestId, type, seq: state.generationSequence, active: state.generationActive, endedSeq: state.generationEndedForSequence });
            state.lastMessageRenderAt = Date.now();
            state.pendingRenderSignature = '';
            state.pendingRenderStableCount = 0;
            schedulePostGenerationCompletionCheck();
        };

        add(types.MESSAGE_RECEIVED, acceptLatestMessageEvent);
        add(types.CHARACTER_MESSAGE_RENDERED, acceptLatestMessageEvent);

        add(types.GENERATION_ENDED, () => {
            state.generationActive = false;
            state.generationEndedForSequence = state.generationSequence;
            state.generationEndedAt = Date.now();
            debugGeneration({ kind: 'ended', seq: state.generationSequence, chatLen: getContext()?.chat?.length });
            if (!state.pendingGenerationResult) {
                const context = getContext();
                const chat = context?.chat;
                const latestId = Array.isArray(chat) && chat.length ? chat.length - 1 : null;
                state.pendingGenerationResult = {
                    messageId: latestId,
                    type: state.activeGenerationType,
                    sequence: state.generationSequence,
                };
            }
            state.pendingRenderSignature = '';
            state.pendingRenderStableCount = 0;
            schedulePostGenerationCompletionCheck(140);
        });

        add(types.GENERATION_STOPPED, () => {
            resetGenerationRetryState();
            state.pendingGenerationResult = null;
            state.generationEndedForSequence = 0;
            if (state.generationWaitTimer) clearTimeout(state.generationWaitTimer);
            state.generationWaitTimer = null;
            state.generationActive = false;
        });
    }

    function teardownGenerationWatchers() {
        for (const { source, event, handler } of state.generationWatchers.splice(0)) {
            try { source.removeListener(event, handler); } catch { /* ignore */ }
        }
    }
    function ensureObservers() {
        if (!state.observer && HOST.MutationObserver) {
            state.observer = new HOST.MutationObserver(() => scheduleEnsure());
        }
        const observer = state.observer;
        if (!observer) return;

        for (const selector of ['#send_form', '#movingDivs']) {
            const node = qs(selector);
            if (node && !state.observedNodes.has(node)) {
                try {
                    observer.observe(node, { childList: true, subtree: true });
                    state.observedNodes.add(node);
                } catch { /* ignore */ }
            }
        }

        if (DOC.body && !state.bodyObserver) {
            try {
                state.bodyObserver = new HOST.MutationObserver(() => {
                    syncRegenerateState();
                    scheduleEnsure();
                });
                state.bodyObserver.observe(DOC.body, { attributes: true, attributeFilter: ['data-generating', 'class'] });
            } catch { /* ignore */ }
        }
    }

    let ensureTimer = null;
    function scheduleEnsure() {
        if (state.destroyed || ensureTimer) return;
        ensureTimer = setTimeout(() => {
            ensureTimer = null;
            ensureCore();
        }, 90);
    }

    function ensureCore() {
        if (state.destroyed) return;
        installToastrEverywhere();
        ensureWandMenuEntry();
        ensureRegenerateButton();
        ensureQrBar();
        ensureToolbox();
        ensureObservers();
        syncRegenerateState();
        setupGenerationWatchers();
        renderShortcutButtons();
        renderShortcutPreview();
    }

    function start() {
        if (state.destroyed) return;
        if (!DOC?.body) {
            setTimeout(start, 250);
            return;
        }

        injectStyle();
        ensureCore();
        loadPanelPosition();
        installToastrEverywhere();

        const fastTimer = setInterval(() => {
            if (state.destroyed) return;
            installToastrEverywhere();
            ensureCore();
            scanAutoConfirmPopups();
        }, 1200);
        state.timers.add(fastTimer);

        const autoConfirmTimer = setInterval(() => {
            if (state.destroyed) return;
            scanAutoConfirmPopups();
        }, 350);
        state.timers.add(autoConfirmTimer);

        const livenessTimer = setInterval(() => {
            if (state.destroyed) return;
            try {
                const frame = window.frameElement;
                if (frame && !frame.isConnected) api.destroy();
            } catch { /* ignore */ }
        }, 1000);
        state.timers.add(livenessTimer);

        const floatTimer = setInterval(() => {
            if (state.destroyed) return;
            scanFloatingWindows();
        }, 2800);
        state.timers.add(floatTimer);

        const onResize = () => fitPanelIntoViewport();
        HOST.addEventListener?.('resize', onResize);
        HOST.visualViewport?.addEventListener?.('resize', onResize);
        HOST.visualViewport?.addEventListener?.('scroll', onResize);
        state.cleanups.push(() => {
            HOST.removeEventListener?.('resize', onResize);
            HOST.visualViewport?.removeEventListener?.('resize', onResize);
            HOST.visualViewport?.removeEventListener?.('scroll', onResize);
        });

        scanFloatingWindows();
    }

    const api = {
        version: VERSION,
        host: HOST,
        openFloatingShortcut,
        scanFloatingWindows,
        autoDetectFloatingWindows,
        getFixedFloatingCandidates,
        measureFloatingElement,
        isSkippedFloatingElement,
        fitPanelIntoViewport,
        getViewportBounds,
        isSmallRect,
        isShownMeasurement,
        getDebugState() {
            return {
                settings: {
                    enableRegenerate: state.enableRegenerate,
                    enableQrEnhance: state.enableQrEnhance,
                    qrToggleSide: state.qrToggleSide,
                    collectShortcuts: state.collectShortcuts,
                },
                lastToggleTrace: state.lastToggleTrace || null,
                generationDebug: state.generationDebug.slice(-80),
                managed: Array.from(state.managed.values()).map(record => ({
                    key: record.key,
                    title: record.title,
                    connected: Boolean(record.el?.isConnected),
                    hiddenByUs: record.hiddenByUs,
                    visible: isFloatingRecordVisible(record),
                    element: record.el ? {
                        tag: record.el.tagName,
                        id: record.el.id,
                        className: String(record.el.className || '').slice(0, 160),
                        titleAttr: record.el.getAttribute?.('title'),
                        ariaLabel: record.el.getAttribute?.('aria-label'),
                        text: (record.el.innerText || record.el.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 100),
                    } : null,
                    visualDisplay: (() => {
                        const visual = getFloatingVisualElement(record);
                        return visual ? HOST.getComputedStyle?.(visual)?.display : null;
                    })(),
                })),
            };
        },
        destroy() {
            if (state.destroyed) return;
            state.destroyed = true;

            if (state.pickMode) {
                try { state.pickCleanup?.(); } catch { /* ignore */ }
                state.pickMode = false;
                state.pickCleanup = null;
                DOC.body?.classList.remove('tt-fw-pick-mode');
                qs('#tt-pick-hint')?.remove();
            }

            for (const timer of state.timers) clearInterval(timer);
            state.timers.clear();
            if (ensureTimer) clearTimeout(ensureTimer);
            try { state.observer?.disconnect(); } catch { /* ignore */ }
            try { state.bodyObserver?.disconnect(); } catch { /* ignore */ }

            for (const cleanup of state.cleanups.splice(0)) {
                try { cleanup(); } catch { /* ignore */ }
            }

            for (const observer of state.hideObservers.values()) {
                try { observer.disconnect(); } catch { /* ignore */ }
            }
            state.hideObservers.clear();

            // Bất kể bảng trạng thái có đầy đủ hay không, đều khôi phục các lối vào nổi bị script này ẩn khỏi toàn bộ DOM thông thường / Shadow DOM.
            for (const root of getDocumentRoots()) {
                try {
                    for (const element of root.querySelectorAll('[data-tt-dock-hidden], .tt-force-hidden')) {
                        try {
                            element.classList.remove('tt-force-hidden');
                            unhideFloatingElement(element);
                        } catch { /* ignore */ }
                    }
                    for (const element of root.querySelectorAll('[data-tt-floating-window]')) {
                        try { element.removeAttribute('data-tt-floating-window'); } catch { /* ignore */ }
                    }
                    for (const element of root.querySelectorAll('[data-tt-dock-display]')) {
                        try { delete element.dataset.ttDockDisplay; } catch { /* ignore */ }
                    }
                    for (const element of root.querySelectorAll('[data-tt-auto-confirm-handled]')) {
                        try { delete element.dataset.ttAutoConfirmHandled; } catch { /* ignore */ }
                    }
                } catch { /* ignore */ }
            }

            qs(`#${ROOT_ID}`)?.remove();
            qs(`#${STYLE_ID}`)?.remove();
            qs(`#${REGEN_ID}`)?.remove();
            qs(`#${QR_TOGGLE_ID}`)?.remove();
            qs('#tt-wand-container')?.remove();
            qs('#tt-shortcut-bar')?.remove();
            for (const bar of qsa('#qr--bar')) {
                bar.classList.remove('tt-qr-enhanced', 'tt-qr-collapsed', 'tt-qr-expanded', 'tt-qr-toggle-at-left', 'tt-qr-toggle-at-right');
            }

            teardownGenerationWatchers();
            cancelScheduledGenerationRetry();
            cancelScrollCorrection();
            if (state.generationWaitTimer) clearTimeout(state.generationWaitTimer);
            state.generationWaitTimer = null;
            restoreToastr();
            try { if (HOST[APP_KEY] === api) delete HOST[APP_KEY]; } catch { /* ignore */ }
            if (!IS_HOST_FRAME) {
                try { if (window[APP_KEY] === api) delete window[APP_KEY]; } catch { /* ignore */ }
            }
        },
    };

    try { HOST[APP_KEY] = api; } catch { /* ignore */ }
    if (!IS_HOST_FRAME) {
        try { window[APP_KEY] = api; } catch { /* ignore */ }
    }

    // Khi Tavern Helper tắt/xóa script, iframe chứa script sẽ bị gỡ bỏ, bắt buộc phải chủ động dọn dẹp UI trong trang máy chủ (host) tại đây.
    const onRuntimePageHide = () => {
        try { api.destroy(); } catch { /* ignore */ }
    };
    try { window.addEventListener('pagehide', onRuntimePageHide, { once: true }); } catch { /* ignore */ }
    try { window.addEventListener('unload', onRuntimePageHide, { once: true }); } catch { /* ignore */ }
    state.cleanups.push(() => {
        try { window.removeEventListener('pagehide', onRuntimePageHide); } catch { /* ignore */ }
        try { window.removeEventListener('unload', onRuntimePageHide); } catch { /* ignore */ }
    });

    if (DOC.readyState === 'loading') {
        DOC.addEventListener('DOMContentLoaded', start, { once: true });
    } else {
        start();
    }
})();
